# ══════════════════════════════════════════════════════════════════
# 3. FIT MODELS & EXTRACT RESULTS
# ══════════════════════════════════════════════════════════════════
store      <- list()
fit_stats  <- list()
models     <- list()

for (i in seq_along(my_models)) {
  model_name     <- names(my_models)[[i]]
  formula_string <- my_models[[i]]
  cat(i, model_name, formula_string, "\n")
  
  cox_fit <- coxph(
    as.formula(formula_string),
    data    = adata_ipw,
    weights = wt,
    robust  = TRUE
  )
  
  # ── per-term results ─────────────────────────────────────────────
  dx <- tidy(cox_fit, conf.int = FALSE) %>%
    mutate(
      ci95_lo    = estimate - qnorm(0.975) * robust.se,
      ci95_hi    = estimate + qnorm(0.975) * robust.se,
      ci50_lo    = estimate - qnorm(0.750) * robust.se,
      ci50_hi    = estimate + qnorm(0.750) * robust.se,
      hr         = exp(estimate),
      hr_ci95_lo = exp(ci95_lo),
      hr_ci95_hi = exp(ci95_hi),
      hr_ci50_lo = exp(ci50_lo),
      hr_ci50_hi = exp(ci50_hi),
      ci_label   = sprintf("%.2f (%.2f, %.2f)", hr, hr_ci95_lo, hr_ci95_hi),
      model_name = model_name,
      formula    = formula_string
    ) %>%
    select(model_name, formula, term,
           hr, hr_ci50_lo, hr_ci50_hi, hr_ci95_lo, hr_ci95_hi,
           p.value, ci_label)
  
  # ── global fit statistics ────────────────────────────────────────
  s <- summary(cox_fit)
  fit_stats[[model_name]] <- data.frame(
    model_name   = model_name,
    formula      = formula_string,
    n            = s$n,
    n_events     = s$nevent,
    concordance  = s$concordance[["C"]],
    concordance_se = s$concordance[["se(C)"]],
    #r2_max       = s$rsq[["max"]],        # Nagelkerke-style max R²
    r2           = s$rsq[["rsq"]],
    lr_test      = s$logtest[["test"]],   # likelihood ratio test stat
    lr_df        = s$logtest[["df"]],
    lr_p         = s$logtest[["pvalue"]],
    wald_test    = s$waldtest[["test"]],
    wald_df      = s$waldtest[["df"]],
    wald_p       = s$waldtest[["pvalue"]],
    score_test   = s$sctest[["test"]],    # logrank / score test
    score_df     = s$sctest[["df"]],
    score_p      = s$sctest[["pvalue"]],
    robust_score = s$robscore[["test"]],  # robust score test
    robust_score_p = s$robscore[["pvalue"]]
  )
  
  store[[model_name]] <- dx
  models[[model_name]] <- cox_fit
}

